import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N = float(data[0])
    K = int(data[1])

    if K == 0:
        result = N
    else:
        divisor = 2 ** K
        result = N / divisor

    # Round to 2 decimal places
    result = round(result, 2)

    # Format output - show as integer if no decimal part, otherwise show decimals
    if result == int(result):
        print(int(result))
    else:
        print(f"{result:.2f}")

if __name__ == "__main__":
    main()
